# Q13 round-2 patch: global significance, ring null, HDO LTE column; qualifies Q13a/Q13f (idempotent). Run after build_report_q13.py:  python3 -I build_report_q13g.py
import json
p='/output/report.json'; r=json.load(open(p))
r['results']=[x for x in r['results'] if not x['quantity'].startswith(('Q13g','Q13h'))]
MARK='[ROUND2] '
G=("POST-SELECTION CALIBRATION (Q13g): the 4.4 sigma is a POINTWISE value at a position chosen as the HCN blue-lobe peak. Blind search of the Xb4d E map (E=HCN-0.574*HCO+, 2375-2575 km/s, 1.05\" beam, r=1\" disk mean, field r<=7.5\", 141 independent 1\" apertures): the lobe (E=0.116 at (-0.2,-4.7)\") is the highest of 12 local maxima (next 0.075 at (-4.7,+3.4)\", 0.064 at (2.4,1.9)\"; the rank alone is p=1/12); with the E-map robust sigma 0.0264 (includes real structure) z=4.40, p_local=5.4e-6, trials-corrected p_global=7.6e-4 = 3.2 sigma one-sided (3.0 sigma with the random-aperture sigma 0.027). The red mirror window peaks at 0.156 (0.134 at (-4.7,+3.4)\", 0.098 at (-5.3,-2.9)\") with map sigma 0.040, i.e. the field has red-side E maxima of 2.9 sigma local (global 0.8 sigma) so the E noise is not purely Gaussian. Sliding 200 km/s line-free windows (HCN 1380-2100 and HCO+ free ranges) give far lower noise (sigma 0.008, max E over the field 0.020-0.027, none near 0.116) but those channels are far from the line and miss the wing/sidelobe/baseline structure of the line window, so they are NOT used for the significance (only as a statement that no instrumental E of this size occurs in emission-free channels). Matched environment (ring of r=1.93\" around S through the lobe, 10-deg steps, E window): excluding the lobe azimuth +-45 deg the ring has mean 0.000, sd 0.015, max 0.031 (lobe is +8.0 sigma of the ring, and the only ring point >0.031); the same ring in the red mirror window has sd 0.039 and max 0.091 (lobe 2.4 sigma above it); the ring around N: blue sd 0.025 max 0.056, red max 0.143. (The reviewer's '4.5\" from S' is the lobe distance from the phase centre; the lobe is 1.93\" = 0.38 kpc S of S.) Result: GLOBAL significance 3.0-3.2 sigma (one-sided), below the 4 sigma bar: E is MARGINAL as a standalone detection of excess HCN over k*HCO+; HDO cannot be excluded and the (separately detected) HCO+ blue wing is the secure part. Caveat: the trials factor assumes the lobe position would have been searched over the whole field (conservative; if the S side 3.5-5.5\" annulus only is searched N_ind~45 and p_global~2.4e-4 = 3.5 sigma).")
for x in r['results']:
    q=x['quantity']
    if q.startswith('Q13a') and MARK not in x['value']:
        x['value']=MARK+"The 4.4 sigma (r=1\") is a POINTWISE significance at a position selected on the same data; trials-corrected over the field it is 3.0-3.2 sigma (Q13g). "+x['value']
    if q.startswith('Q13f') and MARK not in x['value']:
        x['value']=MARK+"Qualification: E (HCN excess over k*HCO+) has pointwise 4.4 sigma but GLOBAL (post-selection) significance 3.0-3.2 sigma (blind search over the field, 141 independent apertures; Q13g), so it is MARGINAL (confidence medium-low); the lobe is an 8 sigma azimuthal outlier on the ring at the same distance from S (so S-nucleus residuals do not make it), HDO as the whole of E would need N(HDO)~1.5-2e15 cm-2 which is 20-2000x above any plausible HDO/H2 for the HCO+-implied N(H2) (Q13h; strongly disfavoured but not excluded, no second HDO line in the data). Text below predates this calibration; 'reproduced'/'real' in it mean pointwise. "+x['value']
        x['confidence']='medium-low'
        x['uncertainty']="E 4.4 sigma pointwise, 3.0-3.2 sigma global (Xb4d); blend fraction see Q13c; ratio see Q13b"
A=lambda n,v:{"name":n,"value":v}
r['results'].append({"quantity":"Q13g: global (post-selection) significance of the S-lobe HCN excess E and matched-environment (ring) null","value":G,
 "uncertainty":"global 3.0-3.2 sigma (one-sided); depends on N_ind (141 field; ~45 for the S annulus) and on the Gaussian tail assumption","unit":"sigma",
 "confidence":"medium","evidence":"scripts/q13g_global.py -> out/q13/q13g.log, q13g_sliding.csv, q13g_Sannulus.csv","target":"Soutflow",
 "assumptions":[A("E map","Xb4d cubes convolved to circular 1.05\", per-pixel linear baseline, window sums, disk mean r=1\" by FFT convolution; field r<=7.5\"; k=0.574"),
  A("trials","N_ind = pi*7.5^2/(1.133*1.05^2) = 141; p_global=1-(1-p_local)^N_ind, Gaussian with sigma = robust MAD of the E-window map over the field")]})
H=open('/workspace/out/q13/q13h.log').read()
r['results'].append({"quantity":"Q13h: LTE column of HDO 2(2,0)-3(1,3) required if the whole lobe excess E were HDO, vs plausible HDO/H2","value":
 "E=0.115+-0.027 Jy/beam km/s in the 1.05\" beam = 1.80+-0.42 K km/s (beam-filling) at 266.161 GHz (Eu=157.2 K, A=1.75e-5 s-1, g_u=5, Q(T)=588*(T/300)^1.5; thin LTE, CMB corrected). Required N(HDO) = 2.6e15 (50 K), 1.5e15 (100 K), 1.7e15 (150 K), 2.0e15 (200 K), 2.8e15 (300 K) cm-2 (+-25%), larger by (1.05\"/size)^2 if the emitter is smaller than the beam. The parent gas (HCO+ 2685-2885 at the same aperture, 7.8 K km/s) has thin-LTE N(HCO+) = 0.65-1.1e13 (100-200 K), so HDO/HCO+ would have to be 170-240 (a lower limit on N(HCO+) only if HCO+ is thin; thick HCO+ raises it by a few). With X(HCO+)=1e-9..1e-8: N(H2)=0.7-11e21 and HDO/H2 = 1.7e-7..2.4e-6 (T 100-300 K) - i.e. 17-1000x above the reviewer's 1e-9-1e-8 and at/above the highest Galactic hot-core/hot-corino values (~1e-7). Forward: for X(HDO)=1e-9..1e-8 and N(H2) from HCO+ the HDO line would be 0.06-6 mJy/beam km/s versus the observed E = 115, i.e. 20-2000x too weak. Independent check from mass: the Q3b dense mass 1.4e6-6.5e6 Msun over the 3x2.7\" box gives <N(H2)>~1e21 cm-2, needing HDO/H2~2e-6 (and gas at 100-300 K over ~0.5 kpc, which the HCN/HCO+ ladder (Q12: Tkin 16-40 K) does not support). VERDICT: E as HDO is strongly disfavoured chemically/energetically; not excluded observationally (no second HDO line, HDO/H2 of the lobe is unmeasured).",
 "uncertainty":"N(HDO) +-25% (E error, Q(T) 10%); HDO/H2 uncertain by >10x through N(H2)","unit":"cm-2",
 "confidence":"medium-low","evidence":"scripts/q13h_hdo_lte.py -> out/q13/q13h.log","target":"Soutflow",
 "assumptions":[A("spectroscopy","Splatalogue/JPL line list dump of Q0 (out/splatalogue_raw.csv): HDO 266161.07 MHz, Eu 157.21 K, log A -4.756, S mu2 0.399 D2; Q_rot from the asymmetric-rotor formula (spin factor cancels)"),
  A("filling","source fills the 1.05\" beam; Tex=Tkin 50-300 K; line optically thin (tau<<1 at these columns for 150 km/s width)")]})
i=r['interpretation'].find('\n\nQ13:')
if i>=0 and 'ROUND2' not in r['interpretation']:
    r['interpretation']+=" [ROUND2] Q13 calibration: the S-lobe HCN excess over k*HCO+ is 4.4 sigma pointwise but 3.0-3.2 sigma after correcting for the position choice (marginal); the HDO blend as its sole origin is chemically disfavoured (needs HDO/H2>~1e-7) but not excluded."
json.dump(r,open(p,'w'),indent=1); print(len(r['results']))
